import { Container, Row, Table } from "react-bootstrap";
import React, { useState, useEffect } from "react";
import WorksListContainer from "./WorksListContainer";
import ButtonsOnOff from "./layout/ButtonsOnOff";
import ButtonsEditDelete from "./layout/ButtonsEditDelete";
import FormAddObject from "./layout/ObjectFromAdd";

function ExhibitsListContainer({ socket, editMode }) {
  const [showModal, setShowModal] = useState(false);
  const [db, setDB] = useState({ exhibits: [], works: [], units: [] });

  useEffect(() => {
    // https://stackoverflow.com/questions/56800694/what-is-the-expected-return-of-useeffect-used-for
    let isValid = true;
    if (socket) {
      socket.on("database", (data) => {
        if (isValid && !showModal) {
          setDB(data);
        }
      });
    }
    return () => {
      isValid = false;
    };
  }, [socket, showModal]);

  const ButtonGroupOnOffEditDelete = ({ exhibit }) => {
    exhibit.type = "exhibit";

    if (editMode) {
      return (
        <ButtonsEditDelete
          socket={socket}
          object={exhibit}
          showModal={showModal}
          setShowModal={setShowModal}
        ></ButtonsEditDelete>
      );
    } else {
      return <ButtonsOnOff socket={socket} object={exhibit}></ButtonsOnOff>;
    }
  };

  const exhibitListItems = db.exhibits.map((exhibit) => (
    <Container key={"exhibit-container" + exhibit.id}>
      <Row>
        <Table striped bordered className="p-0" size="sm">
          <thead>
            <tr>
              <th
                style={{
                  minWidth: "150px",
                  width: "200px",
                  overflow: "hidden",
                }}
              >
                {exhibit.name}
                {editMode && <a href={`api/exhibit/${exhibit.id}`}> #</a>}
              </th>

              <th></th>
              <th style={{ width: "90px" }}>
                <ButtonGroupOnOffEditDelete
                  exhibit={exhibit}
                ></ButtonGroupOnOffEditDelete>
              </th>
            </tr>
          </thead>
          <tbody>
            <WorksListContainer
              db={db}
              socket={socket}
              editMode={editMode}
              exhibit={exhibit}
              showModal={showModal}
              setShowModal={setShowModal}
            ></WorksListContainer>
          </tbody>
        </Table>
      </Row>
    </Container>
  ));

  return (
    <>
      {editMode && (
        <Container>
          <Row>
            <Table striped bordered className="p-0" size="sm">
              <tbody>
                <FormAddObject socket={socket} type={"exhibit"} />
              </tbody>
            </Table>
          </Row>
        </Container>
      )}
      {exhibitListItems}
    </>
  );
}

export default ExhibitsListContainer;

