import ButtonsOnOff from "./layout/ButtonsOnOff";
import ButtonsEditDelete from "./layout/ButtonsEditDelete";
import FormAddObject from "./layout/ObjectFromAdd";
import UnitModalButton from "./layout/UnitModalButton";
import UnitListContainer from "./UnitContainer";

function WorksListContainer({
  db,
  socket,
  editMode,
  exhibit,
  showModal,
  setShowModal,
}) {
  const EditButtons = ({ work }) => {
    if (editMode) {
      return (
        <>
          <ButtonsEditDelete
            socket={socket}
            object={work}
            showModal={showModal}
            setShowModal={setShowModal}
          ></ButtonsEditDelete>
          <UnitModalButton
            socket={socket}
            parentObject={work}
            showModal={showModal}
            setShowModal={setShowModal}
          ></UnitModalButton>
        </>
      );
    } else {
      return <ButtonsOnOff socket={socket} object={work}></ButtonsOnOff>;
    }
  };

  const workListItems = db.works.map((work) => {
    if (exhibit.id === work.parentId) {
      return (
        <tr key={"work-tr-" + work.id}>
          <td>
            {" "}
            {work.name}
            {editMode && <a href={`api/work/${work.id}`}> #</a>}
          </td>
          <td>
            <UnitListContainer
              db={db}
              socket={socket}
              parentObject={work}
              editMode={editMode}
              showModal={showModal}
              setShowModal={setShowModal}
            ></UnitListContainer>
          </td>
          <td>
            <EditButtons work={work}></EditButtons>
          </td>
        </tr>
      );
    }
    return null;
  });
  return (
    <>
      {editMode && (
        <FormAddObject
          socket={socket}
          type={"work"}
          parentId={exhibit.id}
        ></FormAddObject>
      )}
      {workListItems}
    </>
  );
}
export default WorksListContainer;

