        return "success";
      default:
        return "warning";
    }
  };

  const submitDelete = (e, unit) => {
    e.preventDefault();
    socket.emit("command", { cmd: "delete", data: unit });
  };

  const ButtonDelete = ({ unit }) => {
    if (editMode) {
      return (
        <Button
          size="sm"
          className="m-0 ms-2 float-end border border-dark"
          variant="danger"
          onClick={(e) => {
            submitDelete(e, unit);
          }}
        >
          Delete
        </Button>
      );
    } else return null;
  };

  const submitShellCommand = (e, object, state) => {
    e.preventDefault();
    socket.emit("changeState", { object: object, state: state });
    console.log();
  };
  const ButtonsShell = ({ object }) => {
    const ButtonShellGroup = object.args.commands.map((command, idx) => {
      if (command.name === "Status") return null;
      if (command.name === "Reachable") return null;
      return (
        <>
          <Button
            key={"shellbutton-" + idx}
            variant="secondary"
            size="sm"
            className="ms-2"
            onClick={(e) => {
              submitShellCommand(e, object, command);
            }}
          >
            {command.name}
          </Button>
        </>
      );
    });
    return (
      <div size="sm" className="float-end">
        {ButtonShellGroup}
      </div>
    );
  };

  const UnitTooltip = ({ unit }) => {
    return <>{JSON.stringify(unit)}</>;
  };

  const UnitItemWrapper = ({ unit }) => {
    if (unit.automation) {
      return (
        <OverlayTrigger
          overlay={
            <Tooltip>
              <UnitTooltip unit={unit}></UnitTooltip>
            </Tooltip>
          }
        >
          <a
            href={"http://" + unit.host}
            alt={JSON.stringify(unit)}
            target="_blank"
            rel="noreferrer"
            className="p-0"
          >
            <Badge
              key={unit.id}
              bg={stateIndicator(unit.state)}
              className="me-1 m-1 mb-1"
            >
              <UnitItem unit={unit} />
              <ButtonDelete unit={unit} />
            </Badge>
          </a>
        </OverlayTrigger>
      );
    } else {
      return (
        <Card className="p-0 py-1 ps-1 my-1 ms-5" bg="light" key={unit.id}>
          <Card.Body className="p-0 m-0">
            <a
              href={"http://" + unit.host}
              target="_blank"
              rel="noreferrer"
              alt={JSON.stringify(unit)}
            >
              <Badge
                key={unit.id}
                bg={stateIndicator(unit.state)}
                className="me-1 mb-1 m-0 p-1"
              >
                <UnitItem unit={unit} />
              </Badge>
            </a>
            <ButtonDelete unit={unit} />
            {unit.unitType !== "shell" ? (
              <ButtonsOnOff socket={socket} object={unit} />
            ) : (
              <ButtonsShell object={unit} />
            )}
          </Card.Body>
        </Card>
      );
    }
  };
  const UnitItem = ({ unit }) => {
    switch (unit.unitType) {
      case "projector":
        return (
          <>
            <Projector className="me-1" size={16} />
            {unit.host.replace("192.168.", "")}
            {unit.args.name !== undefined && unit.args.name.length > 0 && (
              <> / {unit.args.name}</>
            )}
          </>
        );

      case "netio":
        return (
          <>
            <Outlet className="me-1" size={16} />
            N-
            {unit.host
              .replace("netzwerksteckdose-netio-", "")
              .replace(".zkm.de", "")}{" "}
            <em>{Number.parseInt(unit.args.port) + 1}</em>
            {unit.args.name.length > 0 && " / " + unit.args.name}
          </>
        );
      case "anel":
        return (
          <>
            <Plug className="me-1" size={16} />
            A-{unit.host.replace("netzwerksteckdose", "")}{" "}
            <em>{Number.parseInt(unit.args.port) + 1}</em>
            {unit.args.name.length > 0 && " / " + unit.args.name}
          </>
        );
      case "shell":
        return (
          <>
            <Terminal className="me-1" size={16} />
            {unit.args.name.length > 0 && unit.args.name}
          </>
        );
      default:
        return null;
    }
  };

  const UnitListItemsAutomation = db.units.map((unit) => {
    if (unit.parentId === parentObject.id && unit.automation)
      return <UnitItemWrapper unit={unit} key={unit.id} />;
    return null;
  });

  const UnitListItemsNoAutomationContainer = () => {
    return <>{UnitListItemsNoAutomation}</>;
    //const units = _.filter(db.units, {
    //  parentId: parentObject.id,
    //  automation: false,
    //});

    // @TODO
    //if (units.length === 1) return <>{UnitListItemsNoAutomation}</>;
    //if (units.length > 1)
    //  return (
    //    <Accordion
    //      defaultActiveKey="0"
    //      key={"unitListNoAutomation-" + parentObject.id}
    //    >>>>>>>> 4e4c3c610c64498bc42e6c7eeab2d0a251d80a4b
    //      <Accordion.Item eventKey={parentObject.id}>
    //        <Accordion.Header>No Automation [{units.length}]</Accordion.Header>
    //        <Accordion.Body>{UnitListItemsNoAutomation}</Accordion.Body>
    //      </Accordion.Item>
    //    </Accordion>
    //  );
    //else return null;
  };

  const UnitListItemsNoAutomation = db.units.map((unit, idx) => {
    if (unit.parentId === parentObject.id && !unit.automation)
      return <UnitItemWrapper unit={unit} key={unit.id} />;
    return null;
  });

  return (
    <div>
      <div key={"unitListAutomation-" + parentObject.id}>
        <Card className="p-0 m-0" border="success" bg="">
          <Card.Body className="p-0 px-1">{UnitListItemsAutomation}</Card.Body>
        </Card>
      </div>
      <div key={"unitListNoAutomation-" + parentObject.id}>
        <UnitListItemsNoAutomationContainer />
      </div>
    </div>
  );
}

export default UnitListContainer;

