import { Button, ButtonGroup } from "react-bootstrap";
import Modal from "./ObjectModalEdit";

function ButtonsEditDelete({ socket, object, showModal, setShowModal }) {
  const handleClose = () => {
    setShowModal(false);
  };

  const submitDelete = (e, object) => {
    e.preventDefault();
    console.log("Send delete %s", object.id);
    socket.emit("command", { cmd: "delete", data: object });
  };
  const submitEdit = (e, object) => {
    console.log("submit Edit Button Press");
    e.preventDefault();
    socket.emit("command", { cmd: "update", data: object });
    setShowModal(object.id);
  };
  const EditModal = () => {
    if (showModal === object.id) {
      return (
        <Modal
          socket={socket}
          object={object}
          handleClose={handleClose}
        ></Modal>
      );
    } else return null;
  };
  return (
    <>
      <ButtonGroup className="float-end" size="sm">
        <Button
          variant="secondary"
          onClick={(e) => {
            submitEdit(e, object);
          }}
        >
          Edit
        </Button>
        <Button
          variant="danger"
          onClick={(e) => {
            submitDelete(e, object);
          }}
        >
          Delete
        </Button>
      </ButtonGroup>
      <EditModal></EditModal>
    </>
  );
}

export default ButtonsEditDelete;

