import React, { useState } from "react";
import ButtonGroup from "react-bootstrap/ButtonGroup";
import ToggleButton from "react-bootstrap/ToggleButton";
import { Power, Projector, Terminal, Ethernet } from "react-bootstrap-icons";
import FormProjector from "../Units/FormProjector";
import FormNetio from "../Units/FormNetio";
import FormShell from "../Units/FormShell";
import FormAnel from "../Units/FormAnel";

function UnitForm({ socket, parentObject, handleModalClose }) {
  const [radioValue, setRadioValue] = useState("1");

  const unitTypes = [
    { name: "Projector", value: "projector" },
    { name: "NetIO", value: "netio" },
    { name: "Anel", value: "anel" },
    { name: "Shell", value: "shell" },
  ];

  const IconGenerator = ({ radioName }) => {
    switch (radioName) {
      case "projector":
        return <Projector className="me-2" />;
      case "netio":
      case "anel":
        return <Power className="me-2" />;
      case "udp":
        return <Ethernet className="me-2" />;
      case "shell":
        return <Terminal className="me-2" />;
      default:
        return null;
    }
  };
  const UnitFormContainer = () => {
    switch (radioValue) {
      case "projector":
        return (
          <FormProjector
            socket={socket}
            parentObject={parentObject}
            handleModalClose={handleModalClose}
          ></FormProjector>
        );
      case "netio":
        return (
          <FormNetio
            socket={socket}
            parentObject={parentObject}
            handleModalClose={handleModalClose}
          ></FormNetio>
        );
      case "anel":
        return (
          <FormAnel
            socket={socket}
            parentObject={parentObject}
            handleModalClose={handleModalClose}
          ></FormAnel>
        );
      case "shell":
        return (
          <FormShell
            socket={socket}
            parentObject={parentObject}
            handleModalClose={handleModalClose}
          ></FormShell>
        );
      default:
        return null;
    }
  };

  return (
    <div className="container">
      <div className="row">
        <ButtonGroup className="mb-2">
          {unitTypes.map((radio, idx) => (
            <ToggleButton
              key={idx}
              id={`unitSelectRadio-${idx}`}
              type="radio"
              variant="secondary"
              name="unitSelectRadio"
              value={radio.value}
              checked={radioValue === radio.value}
              onChange={(e) => setRadioValue(e.currentTarget.value)}
            >
              <IconGenerator radioName={radio.value} />
              {radio.name}
            </ToggleButton>
          ))}
        </ButtonGroup>
        <div className="col">
          <UnitFormContainer />
        </div>
      </div>
    </div>
  );
}

export default UnitForm;

