import React, { useState } from "react";
import { Card, Form, Button, ButtonGroup, InputGroup } from "react-bootstrap";

function FormProjector({ socket, parentObject, handleModalClose }) {
  const initialFormState = {
    host: "",
    port: "",
    password: "",
    name: "",
    automation: true,
  };
  const [FormState, setFormState] = useState(initialFormState);

  const handleInputChange = (e) => {
    setFormState((previousState) => {
      return { ...previousState, [e.target.name]: e.target.value.trim() };
    });
  };
  const handleCheckboxChange = (e) => {
    setFormState((previousState) => {
      return { ...previousState, [e.target.name]: e.target.checked };
    });
  };
  const handleSubmit = (e) => {
    e.preventDefault();
    if (FormState.host.length < 3) {
      console.log("to short");
    } else {
      addUnit();
      if (e.target.id === "saveAndAddNew") {
        setFormState(initialFormState);
      } else {
        handleModalClose();
      }
    }
  };

  const addUnit = () => {
    const unit = {
      parentId: parentObject.id,
      host: FormState.host.toLowerCase(),
      unitType: "projector",
      type: "unit",
      automation: FormState.automation,
      args: {
        password: FormState.password,
        port: FormState.port,
        name: FormState.name,
      },
    };
    socket.emit("command", {
      cmd: "add",
      data: unit,
    });
  };

  return (
    <Card>
      <Card.Header>Add New Projector</Card.Header>
      <Card.Body>
        <Form>
          <InputGroup className="mb-3">
            <InputGroup.Text style={{ width: "100px" }}>Host</InputGroup.Text>
            <Form.Control
              name="host"
              placeholder="Host / IP"
              onChange={handleInputChange}
              value={FormState.host}
            />
            <Form.Control
              name="port"
              placeholder="Port (Leave blank for default)"
              onChange={handleInputChange}
              value={FormState.port}
            />
          </InputGroup>
          <InputGroup className="mb-3">
            <InputGroup.Text style={{ width: "100px" }}>
              Password
            </InputGroup.Text>

            <Form.Control
              name="password"
              onChange={handleInputChange}
              value={FormState.password}
              placeholder="Password (Leave blank for NO Password)"
            />
          </InputGroup>
          <InputGroup className="mb-3">
            <InputGroup.Text style={{ width: "100px" }}>
              Name
            </InputGroup.Text>

            <Form.Control
              name="name"
              onChange={handleInputChange}
              value={FormState.name}
              placeholder="Name (Leave blank for NO Name)"
            />
          </InputGroup>
          <Form.Text muted>
            Default Passwords: <strong>NEC:</strong> No Password{" "}
            <strong>Panasonic:</strong> panasonic{" "}
          </Form.Text>
          <div>
            <Form.Check
              name="automation"
              type="switch"
              id="custom-switch"
              label="Automatic"
              onChange={handleCheckboxChange}
              checked={FormState.automation}
            />
          </div>
          <ButtonGroup>
            <Button type="submit" id="saveAndAddNew" onClick={handleSubmit}>
              Submit & Add new
            </Button>
            <Button
              variant="secondary"
              type="submit"
              onClick={handleSubmit}
              id="saveAndClose"
            >
              Submit & Close
            </Button>
          </ButtonGroup>
        </Form>
      </Card.Body>
    </Card>
  );
}

export default FormProjector;

