import React, { useState } from "react";
import {
  Card,
  Form,
  Button,
  ButtonGroup,
  InputGroup,
  Offcanvas,
} from "react-bootstrap";

function FormShell({ socket, parentObject, handleModalClose }) {
  const initialFormState = {
    name: "",
    commands: [
      { name: "Reachable", cmd: "", onMsg: "", offMsg: "", editable: false },
      { name: "Status", cmd: "", onMsg: "", offMsg: "", editable: false },
      { name: "On", cmd: "", onMsg: "", offMsg: "", editable: true },
      { name: "Off", cmd: "", onMsg: "", offMsg: "", editable: true },
    ],
    automation: true,
  };

  const [FormState, setFormState] = useState(initialFormState);
  const [showOffCanvs, setShowOffCanvas] = useState(false);
  const [debugMsg, setDebugMsg] = useState("Test");

  const handleOffCanvasClose = () => setShowOffCanvas(false);
  const handleOffCanvasShow = () => setShowOffCanvas(true);

  const handleInputChange = (e, idx) => {
    setFormState((previousState) => {
      return { ...previousState, [e.target.name]: e.target.value };
    });
  };

  const handleCheckboxChange = (e) => {
    setFormState((previousState) => {
      return { ...previousState, [e.target.name]: e.target.checked };
    });
  };

  const handleArrayChange = (e, idx) => {
    const test = { ...FormState };
    test.commands[idx][e.target.name] = e.target.value;
    setFormState((previousState) => {
      return { ...previousState, commands: test.commands };
    });
  };

  const handleCommandAdd = () => {
    const commands = FormState.commands;
    commands.push({ name: "", cmd: "", editable: true });
    setFormState((previousState) => {
      return { ...previousState, commands: commands };
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (FormState.name.length < 3) return;
    addUnit();
    if (e.target.id === "saveAndAddNew") {
      setFormState({ ...initialFormState });
    } else {
      handleModalClose();
    }
  };

  const addUnit = () => {
    console.log(FormState);
    const unit = {
      parentId: parentObject.id,
      unitType: "shell",
      type: "unit",
      automation: FormState.automation,
      args: {
        name: FormState.name,
        commands: FormState.commands,
      },
    };
    socket.emit("command", {
      cmd: "add",
      data: unit,
    });
  };

  const ShellTestCommand = (e, idx) => {
    socket.emit(
      "testShellCommand",
      {
        cmd: "testShellCommand",
        data: { commands: FormState.commands[idx] },
      },
      function (response) {
        setDebugMsg(response);
        if (showOffCanvs !== true) handleOffCanvasShow();
      }
    );
  };

  const DebugCanvas = () => {
    return (
      <Offcanvas
        show={showOffCanvs}
        backdrop={false}
        onHide={handleOffCanvasClose}
        style={{ zIndex: "1200" }}
        placement="end"
      >
        <Offcanvas.Header closeButton>
          <Offcanvas.Title>Server Debug Log</Offcanvas.Title>
        </Offcanvas.Header>
        <Offcanvas.Body>
          <div
            style={{
              fontSize: "12px",
              fontFamily: "monospace",
              height: "100%",
            }}
            dangerouslySetInnerHTML={{ __html: debugMsg }}
          />
        </Offcanvas.Body>
      </Offcanvas>
    );
  };

  const ShellUnitContainer = FormState.commands.map((command, idx) => {
    return (
      <Card className="mb-1" key={"shellinput-" + idx}>
        <Card.Body className="py-1">
          <Form.Group className="mb-1">
            {!FormState.automation && command.editable ? (
              <Form.Control
                name="name"
                placeholder={command.name + " Command Name"}
                onChange={(e) => handleArrayChange(e, idx)}
                value={command.name}
                className="mb-1"
              ></Form.Control>
            ) : (
              <Form.Label>{command.name} Command</Form.Label>
            )}
            <InputGroup>
              <Form.Control
                //size="sm"
                as="textarea"
                key={idx}
                name="cmd"
                placeholder={command.name + " Command"}
                onChange={(e) => handleArrayChange(e, idx)}
                value={FormState.commands[idx].cmd}
                style={{ fontSize: "8px", fontFamily: "monospace" }}
              />
              <Button
                variant="outline-secondary"
                id="button-test"
                onClick={(e) => {
                  ShellTestCommand(e, idx);
                }}
              >
                Test (5s)
              </Button>
            </InputGroup>
          </Form.Group>
          {command.name === "Status" && (
            <Form.Group className="mb-1">
              <Form.Label>Command return values</Form.Label>
              <InputGroup className="mb-0">
                <Form.Control
                  name="onMsg"
                  placeholder={command.name + " Command onMsg value"}
                  onChange={(e) => handleArrayChange(e, idx)}
                  value={FormState.commands[idx].onMsg}
                />
                <Form.Control
                  name="offMsg"
                  placeholder={command.name + " Command offMsg value"}
                  onChange={(e) => handleArrayChange(e, idx)}
                  value={FormState.commands[idx].offMsg}
                />
              </InputGroup>
            </Form.Group>
          )}
        </Card.Body>
      </Card>
    );
  });

  return (
    <>
      <Card>
        <Card.Header>Add New Shell</Card.Header>
        <Card.Body>
          <Form>
            <InputGroup className="mb-3">
              <InputGroup.Text style={{ width: "100px" }}>Name</InputGroup.Text>
              <Form.Control
                name="name"
                onChange={handleInputChange}
                value={FormState.name}
                placeholder="Name - at least 3 chars"
              />
            </InputGroup>
            {ShellUnitContainer}

            <div className="row">
              {FormState.automation ? (
                <div className="col">
                  <Form.Check
                    name="automation"
                    type="switch"
                    id="custom-switch"
                    label="Automatic"
                    onChange={handleCheckboxChange}
                    checked={FormState.automation}
                  />
                </div>
              ) : (
                <div className="col">
                  <Button className="float-end" onClick={handleCommandAdd}>
                    Add another Shell Command
                  </Button>
                </div>
              )}
            </div>
            <ButtonGroup>
              <Button type="submit" id="saveAndAddNew" onClick={handleSubmit}>
                Submit & Add new
              </Button>
              <Button
                variant="secondary"
                type="submit"
                onClick={handleSubmit}
                id="saveAndClose"
              >
                Submit & Close
              </Button>
            </ButtonGroup>
          </Form>
        </Card.Body>
      </Card>
      <DebugCanvas key="test" />
    </>
  );
}

export default FormShell;

