import { Container, Row, Button, InputGroup, Form } from "react-bootstrap";
import React, { useState } from "react";

function FormEditObject({ socket, object, handleClose }) {
  const [ObjectInput, setObjectInput] = useState(object.name);

  const handleInputChange = (e) => {
    setObjectInput(e.target.value);
  };
  //const resetInput = () => {
  //  setObjectInput("");
  //};
  const submitForm = (e) => {
    e.preventDefault();
    const name = ObjectInput.toString().trim();
    socket.emit("command", {
      cmd: "update",
      data: { id: object.id, name: name, type: object.type },
    });
    handleClose();
  };

  return (
    <Container>
      <Row>
        <form onSubmit={submitForm}>
          <InputGroup className="mb-3">
            <Form.Control
              placeholder="Edit"
              aria-label=""
              id="EditObjectInput"
              onChange={handleInputChange}
              value={ObjectInput}
            />
            <Button
              variant="primary"
              id="EditObjectSubmit"
              onClick={submitForm}
            >
              Submit
            </Button>
          </InputGroup>
        </form>
      </Row>
    </Container>
  );
}
export default FormEditObject;

