import { Button, InputGroup, Form } from "react-bootstrap";
import React, { useState } from "react";

function FormAddObject({ socket, type, parentId }) {
  const [ObjectInput, setObjectInput] = useState([""]);
  const label = {
    exhibit: ["Add Exhibition"],
    work: ["Add Works"],
  };

  const handleInputChange = (e) => {
    setObjectInput(e.target.value);
  };
  const resetInput = () => {
    setObjectInput("");
  };
  const submitForm = (e) => {
    e.preventDefault();
    const objectNames = ObjectInput.toString().split(",");
    objectNames.map(function (objectName) {
      objectName = objectName.trim();
      if (objectName.length < 1) return null;
      const singleObject = { name: objectName, type: type, parentId: parentId };

      socket.emit("command", {
        cmd: "add",
        data: singleObject,
      });
      return "";
    });
    resetInput();
  };

  return (
    <tr>
      <td colSpan={3}>
        <form onSubmit={submitForm}>
          <InputGroup className="" size="sm">
            <InputGroup.Text>{label[type]}: </InputGroup.Text>
            <Form.Control
              placeholder="Comma separeted Shows"
              aria-label=""
              onChange={handleInputChange}
              value={ObjectInput}
            />
            <Button variant="primary" onClick={submitForm}>
              Submit
            </Button>
          </InputGroup>
        </form>
      </td>
    </tr>
  );
}
export default FormAddObject;

